answer:
"Hello World" на языке C++ будет выглядеть следующим образом:

#include <iostream>

int main() {
    std::cout << "Hello World!";
    return 0;
}

#include <iostream>
using namespace std;

int factorial(int n) {
    return (n == 1 || n == 0) ? 1 : n * factorial(n - 1);
}

int main() {
    int num;
    cout << "Enter a positive number: ";
    cin >> num;
    cout << "Factorial of " << num << " is " << factorial(num);
    return 0;
}
